const FULL_TEXTBOOKS_DB = {"y1_intro":{"id":"y1_intro","title":"موسوعة المدخل للعلوم القانونية (نظرية القانون ونظرية الحق الكاملة)","icon":"⚖️","courseCode":"LAW 101","meta":"شروح كبار الأساتذة: د. عبد الرزاق السنهوري / د. سمير تناغو / د. توفيق فرج","desc":"الكتاب الأكاديمي الشامل والمفصل: دراسة تأصيلية موسعة لماهية القاعدة القانونية وخصائصها، القواعد الآمرة والمكملة ومعايير التمييز بينهما، مصادر القانون والتشريع والعرف ومبادئ الشريعة، نطاق تطبيق القانون من حيث الزمان والمكان، ونظرية الحق الكاملة بأركانها وأشخاصها ومحلها وطرق إثباتها.","topics":["ماهية القانون وخصائص القاعدة","القواعد الآمرة والمكملة والنظام العام","مصادر القانون والتدرج التشريعي","سريان القانون زماناً ومكاناً","أشخاص الحق ومحله"],"chapters":[{"id":"ch1","title":"الباب التمهيدي: ماهية القانون والخصائص الجوهرية للقاعدة القانونية","content":"<h3 class=\\\"book-section-title\\\">المبحث الأول: المفهوم الفلسفي والاصطلاحي للقانون وضرورته الاجتماعية</h3><p>القانون في معناه العام هو مجموعة القواعد العامة المجردة التي تنظم سلوك الأشخاص وعلاقاتهم في المجتمع على وجه الإلزام، والتي تفرضها السلطة العامة بجزاء مادي جبري يوقع على من يخالفها.</p><p>والإنسان مدني بطبعه لا يستطيع العيش في عزلة، واجتماع بني البشر يؤدي حتماً إلى تضارب المصالح وتشابك الرغبات، فلو تُرك كل فرد يقتضي حقه بذراعه لسادت شريعة الغاب وعمّت الفوضى؛ ومن هنا كانت ضرورة وجود قواعد قانونية تضبط حريات الأفراد، وتوفق بين المصلحة الفردية والمصلحة العامة للجماعة، وتكفل استقرار المعاملات وإقامة العدل.</p><h3 class=\\\"book-section-title\\\">المبحث الثاني: الخصائص الثلاث الجوهرية للقاعدة القانونية</h3><p>1. <strong>قاعدة عامة ومجردة:</strong> التجريد يتعلق بنشأة القاعدة وصياغتها؛ فالقاعدة القانونية لا تخاطب شخصاً معيناً باسمه ولا تتناول واقعة بذاتها، بل تخاطب الأشخاص بصفاتهم (كالمشتري، البائع، القاضي، المحامي، الموظف العام، الجاني)، والوقائع بشروطها وأوصافها (كالبيع، الإيجار، القتل، السرقة، التعويض). أما العمومية فتتعلق بتطبيق القاعدة على كل من يستوفي شروطها دون تمييز.</p><p>2. <strong>قاعدة سلوك اجتماعي:</strong> الغاية المباشرة للقانون هي تنظيم النشاط الخارجي للإنسان داخل المجتمع، ولا يعاقب على مجرد النوايا والسرائر الكامنة ما لم تترجم إلى مظهر خارجي مادي محسوس.</p><p>3. <strong>قاعدة مقترنة بجزاء مادي توقعه السلطة العامة جبراً:</strong> عنصر الجزاء المادي هو الضمانة الحقيقية لاحترام القاعدة القانونية وتوقعه السلطة العامة دون ترك اقتضاء الحقوق للأفراد بأنفسهم.</p><div class=\\\"precedent-quote-box\\\">💡 <strong>مبدأ محكمة النقض المصرية:</strong> «العمومية والتجريد هما مناط القاعدة التشريعية؛ فإذا ما سنّ المشرع نصاً ليطبق على واقعة فردية بذاتها منبتة الصلة عن باقي الوقائع المماثلة، فإنه ينحدر إلى مرتبة القرار الإداري الفردي ويفقد حصانته وقوته التشريعية المجردة».</div>"},{"id":"ch2","title":"الباب الأول: القواعد الآمرة والقواعد المكملة والنظام العام والآداب","content":"<h3 class=\\\"book-section-title\\\">المبحث الأول: مفهوم القواعد الآمرة ومعيار النظام العام</h3><p>القواعد الآمرة (Imperative Rules) هي القواعد التي تفرض حكماً باتاً لا يملك الأفراد الاتفاق على استبعاده أو مخالفة مقتضاه، وكل اتفاق على مخالفتها يقع باطلاً بطلاناً مطلقاً بقوة القانون لاتصالها بالنظام العام وحسن الآداب.</p><h3 class=\\\"book-section-title\\\">المبحث الثاني: القواعد المكملة أو المفسرة</h3><p>القواعد المكملة (Supplementary Rules) هي قواعد ملزمة ولكن المشرع وضعها لتنظيم مصالح الأفراد الخاصة حيث يكون لهم حرية تنظيم شؤونهم التعاقدية، ولا تطبق إلا إذا سكت المتعاقدان عن تنظيم المسألة.</p>"}],"quiz":[{"q":"ما هو معيار التفرقة الأساسي بين القاعدة القانونية الآمرة والقاعدة المكملة؟","options":["مدى جواز اتفاق الأفراد على مخالفة حكمها لارتباطها بالنظام العام","كون القاعدة مكتوبة في التشريع أو غير مكتوبة في العرف","تاريخ صدور القانون ونشره بالجريدة الرسمية","درجة المحكمة التي تطبق القاعدة القانونية"],"correct":0,"rationale":"السند: القواعد الآمرة تتصل بالنظام العام والآداب ولا يجوز الاتفاق على مخالفتها، بينما القواعد المكملة تقبل الاتفاق على خلافها."}]},"y1_const":{"id":"y1_const","title":"كتاب القانون الدستوري والنظم السياسية المقارنة","icon":"🏛️","courseCode":"LAW 102","meta":"شروح كبار الأساتذة: د. يحيى الجمل / د. رمزي الشاعر / د. إبراهيم درويش","desc":"الكتاب الجامعي الكامل: النظرية العامة للدولة، سيادة الشعب والأمة، أشكال الحكومات والدساتير الجامدة والمرنة، مبدأ الفصل بين السلطات، والرقابة على دستورية القوانين أمام المحكمة الدستورية العليا.","topics":["أركان الدولة والسيادة","الدساتير الجامدة والمرنة","الفصل بين السلطات","المحكمة الدستورية العليا"],"chapters":[{"id":"ch1","title":"الباب الأول: النظرية العامة للدولة والدساتير","content":"<h3 class=\\\"book-section-title\\\">المبحث الأول: أركان قيام الدولة الثلاثة</h3><p>تقوم الدولة قانوناً باجتماع ثلاثة أركان أساسية: الشعب، الإقليم، والسلطة السياسية الحاكمة ذات السيادة في الداخل والاستقلال في الخارج.</p><h3 class=\\\"book-section-title\\\">المبحث الثاني: جمود الدستور والرقابة الدستورية</h3><p>الدستور الجامد يتطلب لتعديله إجراءات وأغلبية برلمانية واستفتاء شعبياً خاصاً لحماية الحريات العامة من تقلبات الأغلبية البرلمانية العادية.</p>"}],"quiz":[{"q":"تعديل الدستور الجامد يتميز عن الدستور المرن بـ:","options":["اشتراط إجراءات وأغلبية خاصة أشد تعقيداً من تعديل القوانين العادية","أنه لا يجوز تعديله مطلقاً مدى الحياة","أنه يُعدل بقرار إداري من السلطة التنفيذية فقط","أنه غير مكتوب ويعتمد على التقاليد العرفية"],"correct":0,"rationale":"السند: الجمود الدستوري يعني اشتراط قيود وإجراءات تصويت واستفتاء خاصة تختلف عن طريقة سن القوانين العادية لحماية الحقوق والحريات."}]},"y2_civil":{"id":"y2_civil","title":"موسوعة القانون المدني الكاملة (مصادر وأحكام الالتزام)","icon":"⚖️","courseCode":"LAW 201","meta":"شروح كبار الأساتذة: موسوعة الوسيط للدكتور عبد الرزاق السنهوري / د. جميل الشرقاوي / د. عبد الحي حجازي","desc":"الكتاب الأكاديمي الموسوعي الشامل: دراسة متعمقة ومفصلة للنظرية العامة للعقد وتكوينه، الإيجاب والقبول بين غائبين ونظرية العلم، عيوب الرضا (الغلط، التدليس، الإكراه، الاستغلال والغبن)، المحل والسبب، جزاءات البطلان والفسخ ونظرية الظروف الطارئة بالمادة 147، والمسؤولية التقصيرية الكاملة بأركانها وشروطها وتطبيقاتها بالمادة 163 مدني.","topics":["تكوين العقد والتعاقد الإلكتروني","عيوب الرضا الأربعة بالتفصيل","البطلان المطلق والنسبي والفسخ","نظرية الظروف الطارئة المادة 147","المسؤولية التقصيرية المادة 163 ومسؤولية المتبوع"],"chapters":[{"id":"ch1","title":"الباب الأول: النظرية العامة للعقد وتكوين التراضي والتعاقد بين غائبين","content":"<h3 class=\\\"book-section-title\\\">المبحث الأول: مفهوم العقد ومبدأ سلطان الإرادة</h3><p>يقوم القانون المدني المصري على مبدأ «العقد شريعة المتعاقدين» المنصوص عليه في المادة 147 مدني؛ فلا يجوز نقض العقد أو تعديله إلا باتفاق الطرفين أو للأسباب التي يقررها القانون، مع التزام المتعاقدين بتنفيذ العقد طبقاً لما اشتمل عليه وبطريقة تتفق مع ما يوجبه حسن النية ومستلزمات العدالة (المادة 148 مدني).</p><h3 class=\\\"book-section-title\\\">المبحث الثاني: التعاقد بين الغائبين ونظرية العلم بالقبول (المادة 91 مدني)</h3><p>يُعتبر العقد قد تم في المكان والزمان الذي يعلم فيه الموجب بالقبول، ويُفترض قانوناً أن الموجب قد علم بالقبول في المكان والزمان اللذين وصل إليه فيهما هذا القبول ما لم يقم الدليل على عكس ذلك.</p>"},{"id":"ch2","title":"الباب الثاني: عيوب الرضا (الغلط، التدليس، الإكراه، الاستغلال والغبن)","content":"<h3 class=\\\"book-section-title\\\">المبحث الأول: عيوب الإرادة وأثرها الإبطالي</h3><p>الغلط الجوهري (المادتان 120 و121)، التدليس بحيل احتيالية (المادتان 125 و126)، الإكراه بالرهبة المفسدة للرضا (المادتان 127 و128)، والاستغلال لطيش بين أو هوى جامح (المادة 129 مدني) تجعل العقد باطلاً بطلاناً نسبياً (قابلاً للإبطال) لمصلحة من عيب رضاؤه.</p>"},{"id":"ch3","title":"الباب الثالث: المسؤولية التقصيرية الكاملة (المادة 163 مدني) وتطبيقاتها","content":"<h3 class=\\\"book-section-title\\\">المبحث الأول: أركان المسؤولية التقصيرية الثلاثة</h3><p>«كل خطأ سبّب ضرراً للغير يُلزم من ارتكبه بالتعويض» ⬅️ تقوم المسؤولية على تلازم أركان الخطأ والضرر المباشر ورابطة السببية التي تنتفي بالسبب الأجنبي (القوة القاهرة، الحادث المفاجئ، أو خطأ المضرور).</p><div class=\\\"precedent-quote-box\\\">💡 <strong>مبدأ محكمة النقض:</strong> «مسؤولية المتبوع عن عمل تابعه غير المشروع (المادة 174 مدني) هي مسؤولية تبعية ضامنة قائمة على فكرة الكفالة القانونية لحماية المضرور».</div>"}],"quiz":[{"q":"ما هو الأثر المترتب على تحقق عيب من عيوب الإرادة (كالغلط أو التدليس أو الإكراه) في العقد؟","options":["يكون العقد قابلاً للإبطال لمصلحة المتعاقد المعيب رضاؤه","يكون العقد باطلاً بطلاناً مطلقاً بحكم القانون","ينفسخ العقد تلقائياً دون حاجة لحكم قضائي","يستحق المتعاقد تعويضاً دون المساس بصحة العقد"],"correct":0,"rationale":"السند: عيوب الإرادة تجعل العقد باطلاً بطلاناً نسبياً (قابلاً للإبطال) لمصلحة من عيب رضاؤه."}]},"y2_penal":{"id":"y2_penal","title":"موسوعة قانون العقوبات الكاملة (القسم العام - النظرية العامة للجريمة والمجرم)","icon":"🛡️","courseCode":"LAW 202","meta":"شروح كبار الأساتذة: د. محمود نجيب حسني / د. أحمد فتحي سرور / د. مأمون سلامة","desc":"الكتاب الجنائي الأكاديمي الشامل: مبدأ شرعية الجرائم والعقوبات، النطاق الزماني والمكاني لقانون العقوبات، الركن المادي للجريمة (السلوك، النتيجة، السببية الجنائية)، الشروع وتمييزه عن الأعمال التحضيرية (المادة 45 عقوبات)، الركن المعنوي (القصد الجنائي المباشر والاحتمالي، والخطأ غير العمدي)، أسباب الإباحة (الدفاع الشرعي واستعمال الحق)، وموانع المسؤولية والعقاب.","topics":["مبدأ الشرعية الجنائية","الركن المادي والشروع الجنائي","القصد الجنائي والخطأ","الدفاع الشرعي وأسباب الإباحة","المساهمة الجنائية الفاعل والشريك"],"chapters":[{"id":"ch1","title":"الباب الأول: مبدأ الشرعية الجنائية وأحكام الشروع وأسباب الإباحة","content":"<h3 class=\\\"book-section-title\\\">المبحث الأول: أحكام الشروع بالمادة (45) عقوبات</h3><p>الشروع هو البدء في تنفيذ فعل بقصد ارتكاب جناية أو جنحة إذا أُوقف أو خاب أثره لأسباب لا دخل لإرادة الجاني فيها. ومجرد التفكير والتصميم والتحضير وشراء الأدوات لا يعد شروعاً في نظر القانون الجنائي المصري.</p><h3 class=\\\"book-section-title\\\">المبحث الثاني: شروط الدفاع الشرعي (المواد 245 - 251 عقوبات)</h3><p>حق الدفاع الشرعي يبيح رد أي اعتداء حال غير مشروع يهدد النفس أو المال أو نفس الغير أو ماله، بشرط التناسب والضرورة.</p>"}],"quiz":[{"q":"ما هو الضابط القانوني للتمييز بين العمل التحضيري والشروع المعاقب عليه جنائياً؟","options":["البدء في تنفيذ فعل يؤدي حالاً ومباشرة إلى ارتكاب الجريمة","شراء الجاني للأدوات المستخدمة في الجريمة فقط","مجرد التفكير وعقد النية في ارتكاب الجريمة داخل النفس","اعتراف الجاني أمام أصدقائه برغبته في السرقة"],"correct":0,"rationale":"السند: تنص المادة 45 عقوبات على أن الشروع يتطلب البدء في التنفيذ بفعل لا لبس فيه يتجه مباشرة لإتمام الجريمة."}]},"y4_criminal_proc":{"id":"y4_criminal_proc","title":"موسوعة قانون الإجراءات الجنائية والمحاكمات الكاملة","icon":"⚖️","courseCode":"LAW 401","meta":"شروح كبار الأساتذة: د. أحمد فتحي سرور / د. محمود نجيب حسني / د. مأمون سلامة","desc":"الكتاب الإجرائي الجنائي الموسوعي: الدعوى الجنائية وتحريكها وانقضاؤها، مرحلة جمع الاستدلالات والتحريات، حالات التلبس الأربع الحصرية بالمادة 30 إجراءات، بطلان القبض والتفتيش وما يترتب عليه من بطلان الأدلة والاعترافات، سلطات النيابة العامة في التحقيق الابتدائي والحبس الاحتياطي وضماناته، محكمة الجنايات والجنح المستأنفة، والطعن بالنقض الجنائي وأسبابه.","topics":["تحريك وانقضاء الدعوى الجنائية","حالات التلبس الأربع المادة 30","بطلان القبض والتفتيش وما بني عليهما","الحبس الاحتياطي وضماناته الدستورية","الطعن بالنقض الجنائي"],"chapters":[{"id":"ch1","title":"الباب الأول: حالات التلبس الحصرية وبطلان القبض والتفتيش","content":"<h3 class=\\\"book-section-title\\\">المبحث الأول: حالات التلبس الأربع الحصرية بالمادة (30) إجراءات جنائية</h3><ol><li>مشاهدة الجريمة حال ارتكابها.</li><li>مشاهدة الجريمة عقب ارتكابها ببرهة يسيرة.</li><li>تتبع الجاني إثر وقوع الجريمة بصياح المجني عليه أو العامة.</li><li>مشاهدة الجاني بعد وقوع الجريمة بوقت قريب حاملاً أسلحة أو أمتعة أو أدوات يستدل منها على أنه فاعل أو شريك.</li></ol><h3 class=\\\"book-section-title\\\">المبحث الثاني: قاعدة «ما بُني على باطل فهو باطل»</h3><p>إذا وقع القبض أو التفتيش باطلاً لفقدانه سنده الدستوري أو لانتفاء حالة التلبس، ترتب على ذلك بطلان الإجراء وبطلان كل دليل أو اعتراف مستمد منه مباشرة.</p><div class=\\\"precedent-quote-box\\\">💡 <strong>حكم الهيئة العامة لمحكمة النقض:</strong> «التفتيش الباطل لا يولد دليلاً مشروعاً، والدليل المستمد منه معدوم الأثر قانوناً لا تجوز الإدانة بناءً عليه».</div>"}],"quiz":[{"q":"ما هو الأثر الإجرائي المترتب على قيام ضابط الشرطة بتفتيش شخص المتهم دون إذن نيابة وفي غير حالات التلبس القانونية؟","options":["بطلان التفتيش وبطلان كل دليل أو اعتراف مستمد منه مباشرة كأثر حتمي للبطلان","صحة التفتيش متى عثر الضابط على مواد مخدرة","اعتبار الإجراء صحيحاً إذا وافق المتهم لاحقاً","تحويل الجريمة من جناية إلى جنحة"],"correct":0,"rationale":"السند: استقر قضاء محكمة النقض على أن التفتيش الباطل يترتب عليه بطلان الدليل المستمد منه عملاً بالقاعدة الدستورية «ما بني على باطل فهو باطل»."}]}};

