function renderUniversitiesList() {
  const scroll = document.getElementById('uniScroll');
  if (!scroll) return;
  const filtered = currentRegion === 'all' 
    ? EGYPT_UNIVERSITIES 
    : EGYPT_UNIVERSITIES.filter(function(u) { return u.region === currentRegion; });

  let html = '';
  for (let i = 0; i < filtered.length; i++) {
    const u = filtered[i];
    const activeClass = (u.id === currentUniId) ? ' active' : '';
    html += '<button class="uni-card-btn' + activeClass + '" data-uni-id="' + u.id + '">';
    html += '<span>' + u.icon + '</span>';
    html += '<span>' + u.name + '</span>';
    html += '</button>';
  }
  scroll.innerHTML = html;

  const btns = scroll.querySelectorAll('.uni-card-btn');
  btns.forEach(function(btn) {
    btn.addEventListener('click', function() {
      const id = this.getAttribute('data-uni-id');
      selectUniversity(id);
    });
  });
}

